<div class="col-xl-5"><div class="vstack gap-3"><?php if($active):?><section class="card"><div class="card-body"><h2 class="h4">Registrar evento</h2><form method="post" action="<?=H::escape($basePath.'/investimentos/'.$id.'/eventos')?>" class="vstack gap-3"><?=H::fields($csrfToken)?><div><label class="form-label" for="event-type">O que aconteceu?</label><select class="form-select" id="event-type" name="tipo" required><option value="aporte">Fiz um aporte</option><option value="retirada">Fiz uma retirada</option><option value="rendimento">Confirmar rendimento ou perda</option></select></div><div><label class="form-label" for="event-date">Data</label><input class="form-control" id="event-date" type="date" name="data" max="<?=date('Y-m-d')?>" value="<?=date('Y-m-d')?>" required></div><div><label class="form-label" for="event-mode">Quanto rendeu o dinheiro no mês selecionado?</label><select class="form-select" id="event-mode" name="modo"><option value="valor">Valor em reais (use - para perda)</option><option value="percentual">Percentual sobre o saldo na data</option><option value="saldo">Saldo total informado no extrato</option></select><small class="text-secondary">Para aporte ou retirada, informe o valor em reais. A taxa de uma projeção nunca é lançada automaticamente.</small></div><div><label class="form-label" for="event-value">Valor (R$)</label><input class="form-control" id="event-value" name="valor" inputmode="decimal" placeholder="Ex.: 250,00 ou -25,00"></div><div><label class="form-label" for="event-percent">Percentual (%)</label><input class="form-control" id="event-percent" name="percentual" inputmode="decimal" placeholder="Ex.: 1,25 ou -0,5" value="<?=number_format((int)$investment['taxa_referencia_quatro_casas']/10000,4,',','')?>"></div><div><label class="form-label" for="event-description">Descrição opcional</label><input class="form-control" id="event-description" name="descricao" maxlength="160"></div><button class="btn btn-uai-primary">Confirmar e registrar</button></form></div></section><section class="card"><div class="card-body"><details><summary>Editar dados do investimento</summary><form method="post" action="<?=H::escape($basePath.'/investimentos/'.$id.'/editar')?>" class="vstack gap-2 mt-3"><?=H::fields($csrfToken)?><label>Nome<input class="form-control" name="nome" required value="<?=H::escape($investment['nome'])?>"></label><label>Tipo<select class="form-select" name="tipo"><?php foreach($types as $key=>$label):?><option value="<?=H::escape($key)?>" <?=$investment['tipo']===$key?'selected':''?>><?=H::escape($label)?></option><?php endforeach;?></select></label><label>Instituição<input class="form-control" name="instituicao" value="<?=H::escape($investment['instituicao']??'')?>"></label><label>Finalidade<input class="form-control" name="objetivo" value="<?=H::escape($investment['objetivo']??'')?>"></label><button class="btn btn-outline-secondary">Salvar dados</button></form></details></div></section><?php else:?><div class="alert alert-secondary">Investimento arquivado. Reative na área Arquivados para registrar novos eventos.</div><?php endif;?></div></div></div>
<script>
(() => {
  const type = document.getElementById('event-type');
  const mode = document.getElementById('event-mode');
  const value = document.getElementById('event-value');
  const percent = document.getElementById('event-percent');
  if (!type || !mode || !value || !percent) return;
  const refresh = () => {
    const yieldEvent = type.value === 'rendimento';
    (mode.closest('.searchable-select')?.parentElement || mode.parentElement).hidden = !yieldEvent;
    const usePercent = yieldEvent && mode.value === 'percentual';
    percent.parentElement.hidden = !usePercent;
    value.parentElement.hidden = usePercent;
    percent.required = usePercent;
    value.required = !usePercent;
    document.querySelector('label[for="event-value"]').textContent =
      yieldEvent && mode.value === 'saldo' ? 'Saldo informado no extrato (R$)' : 'Valor (R$)';
  };
  type.addEventListener('change', refresh);
  mode.addEventListener('change', refresh);
  refresh();
})();
</script>
